// Detect an already running local process before migration or recovery can touch its data.
async function listening(port,host){return new Promise((resolve,reject)=>{const socket=net.createConnection({port,host}),timer=setTimeout(()=>{socket.destroy();reject(new Error('Could not confirm that the previous server is stopped.'))},1500);socket.once('connect',()=>{clearTimeout(timer);socket.destroy();resolve(true)});socket.once('error',error=>{clearTimeout(timer);socket.destroy();if(['ECONNREFUSED','EHOSTUNREACH','ENETUNREACH'].includes(error.code))resolve(false);else reject(error)});})}
