 const courseId=co?Number(co[1]):cv?db().prepare('SELECT course_id FROM course_versions WHERE id=?').get(Number(cv[1]))?.course_id:null;
 const user=actor||currentUser(req,new URL(req.url,'http://localhost'));if(!user)return;
 if(cm){const allowed=user.role==='trainer'?classPermission(user,cm[1],classAction(req)):user.role==='student'&&(/^\/api\/(?:student\/|missions\/|submissions\/|surveys\/|quizzes\/)/.test(p))&&!!enrollment(cm[1],user.id);if(!allowed)return;}
 if(courseId&&(user.role!=='trainer'||!canViewCourse(user,courseId)||(!isAdminLike(user)&&!hasGrant(user,'course',courseId,p.endsWith('/publish')?'publish':'edit'))))return;
 if(cm&&(/^\/api\/(?:live|student\/(?:guided|runtime|paced)|missions|submissions)\//.test(p)||secondary)&&getClassRow(cm[1])?.status==='completed')throw Object.assign(new Error('This class has finished. Return to your workspace.'),{status:409});
