function setClassState(classId,patch,userId=null){
  const current=getClassState(classId);
  if(patch.expected_revision!==undefined && Number(patch.expected_revision)!==Number(current.revision||0)){const err=new Error('REVISION_CONFLICT');err.status=409;err.current=current;throw err;}
  const next={
    module_id:patch.module_id!==undefined?patch.module_id:current.module_id,
    activity_id:patch.activity_id!==undefined?patch.activity_id:current.activity_id,
    phase:patch.phase!==undefined?patch.phase:current.phase,
    payload:patch.payload!==undefined?patch.payload:current.payload,
    revision:Number(current.revision||0)+1
  };
  if(patch.payload!==undefined){
    next.payload={...(patch.payload||{})};
    if(!Object.prototype.hasOwnProperty.call(next.payload,'presentation_tools')&&current.payload?.presentation_tools)next.payload.presentation_tools=current.payload.presentation_tools;
    if(!Object.prototype.hasOwnProperty.call(next.payload,'projector_theme_override') && current.payload?.projector_theme_override) next.payload.projector_theme_override=current.payload.projector_theme_override;
  }
  db().prepare(`INSERT INTO classroom_state(class_id,module_id,activity_id,phase,payload_json,revision,updated_by,updated_at)
    VALUES(?,?,?,?,?,?,?,CURRENT_TIMESTAMP)
    ON CONFLICT(class_id) DO UPDATE SET module_id=excluded.module_id,activity_id=excluded.activity_id,phase=excluded.phase,payload_json=excluded.payload_json,revision=excluded.revision,updated_by=excluded.updated_by,updated_at=CURRENT_TIMESTAMP`)
    .run(Number(classId),next.module_id,next.activity_id,next.phase,JSON.stringify(next.payload||{}),next.revision,userId||null);
  engine.log(classId,userId,'classroom_updated','classroom',classId,{phase:next.phase,module_id:next.module_id,activity_id:next.activity_id});
  refresh(Number(classId),'classroom'); return getClassState(classId);
}
