  if(aggregation==='image_interaction'){const x=aggregateImageInteraction(def,answers),cl=getClassRow(inst.class_id),key=String(x.asset||'').replace(/^asset:\/\//,'');summary={...summary,total:x.responding_participants,image_points:x.image_points,image_mode:x.mode,image_asset:x.asset,image_asset_url:key&&cl?.course_version_id?`/api/assets/${Number(cl.course_version_id)}/${key.split('/').map(encodeURIComponent).join('/')}`:'',correct_points:x.correct_points,scored_points:x.scored_points,accuracy_percent:x.accuracy_percent};}
  if(aggregation==='drawing_gallery'){const x=aggregateDrawing(def,answers),cl=getClassRow(inst.class_id),key=String(x.asset||'').replace(/^asset:\/\//,'');summary={...summary,drawings:x.drawings,drawing_asset:x.asset,drawing_asset_url:key&&cl?.course_version_id?`/api/assets/${Number(cl.course_version_id)}/${key.split('/').map(encodeURIComponent).join('/')}`:''};}
  if(aggregation==='collaborative_board'){const x=aggregateCollaborativeBoard(def,answers),identity=collaborativeBoardConfig(def).identity_visibility;summary={...summary,total:x.responding_participants,collaborative_board:x.collaborative_board,categories:x.categories,collaborative_identity_visibility:identity};if(identity==='anonymous')answers=answers.map(r=>({anonymous:true,submitted:Array.isArray(r?.answer?.collaborative_board?.notes)&&r.answer.collaborative_board.notes.length>0}));}
  const assessmentMeta=assessmentSummary(def,answers);if(assessmentMeta)summary={...summary,assessment_meta:assessmentMeta};
