function participantPathAggregate(classId,pathId){
  const rows=db().prepare(`SELECT status,COUNT(*) c FROM participant_runtime_state WHERE class_id=? AND path_id=? GROUP BY status`).all(Number(classId),String(pathId));
  const out={total:0,finished:0,working:0,need_help:0};for(const r of rows){out.total+=Number(r.c||0);if(r.status==='finished')out.finished+=Number(r.c||0);if(r.status==='working')out.working+=Number(r.c||0);if(r.status==='need_help')out.need_help+=Number(r.c||0);}return out;
}
function moduleWorkflowProgress(classId,mod,{allowNext=true}={}){
  const wf=effectiveWorkflow(mod);if(!wf?.nodes?.length)return {module_id:mod?.id,title:mod?.title||'',has_workflow:false,complete:false,nodes:[]};
  const nodes=wf.nodes,edges=wf.edges||[],rows=persistedWorkflowRows(classId,mod.id),byId=new Map(nodes.map(n=>[String(n.id),n])),state=new Map(rows.map(r=>[String(r.node_id),r]));
  const explicitDone=id=>['completed','skipped'].includes(state.get(String(id))?.status);
  const selectedFrom=id=>state.get(String(id))?.selected_next_node_id||null;
  const blocked=new Set();
  for(const e of edges){if((e.scope||'class')!=='class')continue;const sel=selectedFrom(e.from);if(sel&&String(e.to)!==String(sel))blocked.add(String(e.to));}
  const pathAgg=new Map();
  for(const n of nodes)if(n.type==='participant_path'&&n.path_id)pathAgg.set(String(n.id),participantPathAggregate(classId,n.path_id));
  const doneForReadiness=id=>{const n=byId.get(String(id));if(!n)return false;if(explicitDone(id))return true;if(n.type==='participant_path'){const a=pathAgg.get(String(id));return !!a&&a.total>0&&a.finished>=a.total;}return false};
  const currentRow=rows.find(r=>r.status==='current');
  let nextIds=[];
  if(!currentRow&&allowNext){
    if(!rows.length&&wf.start_node_id)nextIds=[String(wf.start_node_id)];
    else{
      for(const n of nodes){const id=String(n.id);if(explicitDone(id)||blocked.has(id)||state.get(id)?.status==='current'||n.type==='participant_path')continue;const incoming=edges.filter(e=>String(e.to)===id);if(!incoming.length){continue}
        let relevant=incoming.filter(e=>{const sel=selectedFrom(e.from);return !sel||String(sel)===id});
        if(!relevant.length)continue;
        if(relevant.every(e=>doneForReadiness(e.from)))nextIds.push(id);
      }
    }
  }
  const display=nodes.map(n=>{const id=String(n.id),row=state.get(id),agg=pathAgg.get(id);let status='upcoming';if(row?.status==='completed')status='completed';else if(row?.status==='skipped')status='skipped';else if(row?.status==='current')status='current';else if(blocked.has(id))status='blocked';else if(n.type==='participant_path'&&agg?.total){status=agg.finished>=agg.total?'completed':'working';}else if(nextIds.includes(id))status='next';return {id,title:workflowNodeTitle(mod,n),type:n.type,status,activity_id:n.activity_id||null,mission_id:n.mission_id||null,path_id:n.path_id||null,started_at:row?.started_at||null,completed_at:row?.completed_at||null,selected_next_node_id:row?.selected_next_node_id||null,participant_progress:agg||null};});
  const closing=display.filter(x=>x.type==='closing');const complete=closing.length?closing.every(x=>['completed','skipped'].includes(x.status)):display.filter(x=>x.status!=='blocked').every(x=>['completed','skipped'].includes(x.status));
  return {module_id:mod.id,title:mod.title||'',has_workflow:true,implicit:!!wf.implicit,complete,nodes:display,current:display.find(x=>x.status==='current')||null,next:display.find(x=>x.status==='next')||null};
}
function workflowProgressForClass(classId){
  const content=getCourseContentByClass(classId),mods=content?.course?.modules||[];let nextAllowed=true;const modules=[];
  for(const mod of mods){let m=moduleWorkflowProgress(classId,mod,{allowNext:nextAllowed});if(!m.has_workflow){modules.push(m);continue}if(m.complete){modules.push(m);continue}if(!nextAllowed){m={...m,nodes:m.nodes.map(n=>n.status==='next'?{...n,status:'upcoming'}:n),next:null};}else nextAllowed=false;modules.push(m);}
  const allNodes=modules.flatMap(m=>m.nodes.map(n=>({...n,module_id:m.module_id,module_title:m.title})));return {modules,current:allNodes.find(n=>n.status==='current')||null,next:allNodes.find(n=>n.status==='next')||null};
}
function canStartWorkflowNode(classId,moduleId,nodeId){const p=workflowProgressForClass(classId),n=p.modules.find(m=>String(m.module_id)===String(moduleId))?.nodes.find(x=>String(x.id)===String(nodeId));return n?.status==='next'||n?.status==='current'}
function beginWorkflowNode(classId,moduleId,node,userId,{override=false}={}){
  if(!node)return null;const existing=db().prepare("SELECT node_id FROM class_workflow_progress WHERE class_id=? AND status='current' LIMIT 1").get(Number(classId));if(existing&&String(existing.node_id)!==String(node.id))throw Object.assign(new Error('Finish the current workflow section before starting another one.'),{status:409});if(!override&&!canStartWorkflowNode(classId,moduleId,node.id))throw Object.assign(new Error('Complete the highlighted next section before jumping ahead.'),{status:409});setWorkflowNodeState(classId,moduleId,node.id,'current',userId);engine.log(classId,userId,'workflow_node_started','workflow_node',node.id,{module_id:moduleId,title:workflowNodeTitle(findModule(getCourseContentByClass(classId),moduleId),node)});return node;
}
function completeWorkflowNode(classId,moduleId,nodeId,userId,{selectedNextNodeId=undefined,status='completed'}={}){if(!moduleId||!nodeId)return;setWorkflowNodeState(classId,moduleId,nodeId,status,userId,{selectedNextNodeId});engine.log(classId,userId,status==='skipped'?'workflow_node_skipped':'workflow_node_completed','workflow_node',nodeId,{module_id:moduleId,selected_next_node_id:selectedNextNodeId||null});}
function updateWorkflowSelectedNext(classId,moduleId,nodeId,nextActivityId){if(!moduleId||!nodeId||!nextActivityId)return null;const mod=findModule(getCourseContentByClass(classId),moduleId);if(!mod)return null;const target=workflowNodeForRef(mod,{activityId:nextActivityId});if(!target)return null;const row=db().prepare('SELECT status FROM class_workflow_progress WHERE class_id=? AND module_id=? AND node_id=?').get(Number(classId),String(moduleId),String(nodeId));if(row) setWorkflowNodeState(classId,moduleId,nodeId,row.status,null,{selectedNextNodeId:target.id});return target.id;}
