  if(activity.type==='single_choice' && c.correct_answer!==undefined) return String(answer)===String(c.correct_answer)?pts:0;
  if(activity.type==='numeric_answer' && c.correct_answer!==undefined){ const tol=Number(c.tolerance||0); return Math.abs(Number(answer)-Number(c.correct_answer))<=tol?pts:0; }
