  if(type==='true_false'){const opts=Array.isArray(activity?.content?.options)?activity.content.options:[];return String(optionValue(key?(opts[0]??'True'):(opts[1]??'False')));}
  if(type==='multiple_choice')return key.join(', ');
  if(type==='numeric_answer')return Number(key.tolerance||0)>0?`${key.value} ± ${key.tolerance}`:String(key.value);
  if(type==='matching')return key.map(x=>`${x.left} → ${x.right}`).join('; ');
  if(type==='fill_blanks')return key.map(x=>`${x.label}: ${x.answers.join(' / ')}`).join('; ');
  if(type==='sorting')return key.join(' → ');
