  const avg=rows.length?rows.reduce((n,x)=>n+x.percent,0)/rows.length:0,correct=rows.filter(x=>x.correct).length,partial=rows.filter(x=>x.percent>0&&!x.correct).length,incorrect=rows.filter(x=>x.percent<=0).length;
  return {scored:true,correct_answer:key,correct_answer_display:assessmentAnswerDisplay(activity,key),max_score:maxPossibleActivityScore(activity,activity.type),responses:rows.length,correct_responses:correct,partial_responses:partial,incorrect_responses:incorrect,accuracy_percent:Number(avg.toFixed(2))};
